        var userSource = source.getVariable();
        if (userSource != null && String(userSource).length > 0) {
            // 解析JSON格式的变量
            var userObj = JSON.parse(userSource);
            if (userObj && userObj[0] && userObj[0].host) {
                sourceVal = userObj[0].host;
            }
        }
